+package com.example;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.confirmdialog.ConfirmDialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final MessageStore messageStore;
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<Message> grid = new Grid<>(Message.class, false);
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+        setSpacing(true);
+        setPadding(true);
+
+        add(new H1("Contact"));
+
+        RouterLink aboutLink = new RouterLink("About", AboutView.class);
+        add(aboutLink);
+
+        FormLayout formLayout = new FormLayout();
+        nameField.setWidth("100%");
+        emailField.setWidth("100%");
+        phoneField.setWidth("100%");
+        messageField.setWidth("100%");
+        messageField.setHeight("150px");
+
+        formLayout.add(nameField, emailField, phoneField, messageField, sendButton);
+        add(formLayout);
+
+        grid.removeAllColumns();
+        grid.addColumn(Message::getName).setHeader("Name");
+        grid.addColumn(Message::getMessage).setHeader("Message");
+        grid.setWidth("100%");
+
+        refreshGrid();
+        add(grid);
+
+        sendButton.addClickListener(event -> validateAndSend());
+        nameField.addValueChangeListener(event -> enableSendButton());
+        emailField.addValueChangeListener(event -> enableSendButton());
+        phoneField.addValueChangeListener(event -> enableSendButton());
+        messageField.addValueChangeListener(event -> enableSendButton());
+
+        messageField.addKeyDownListener(com.vaadin.flow.component.Key.ENTER, event -> {
+            if (sendButton.isEnabled()) {
+                validateAndSend();
+            }
+        });
+    }
+
+    private void validateAndSend() {
+        boolean valid = true;
+
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+
+        String name = nameField.getValue().trim();
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        String message = messageField.getValue().trim();
+
+        if (name.isEmpty()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            valid = false;
+        }
+
+        if (!email.isEmpty() && !isValidEmail(email)) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            valid = false;
+        }
+
+        if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            valid = false;
+        }
+
+        if (message.isEmpty()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            valid = false;
+        }
+
+        if (message.length() > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            valid = false;
+        }
+
+        if (valid) {
+            messageStore.addMessage(new Message(name, email, phone, message));
+            nameField.setValue("");
+            emailField.setValue("");
+            phoneField.setValue("");
+            messageField.setValue("");
+            refreshGrid();
+            sendButton.setEnabled(false);
+            Notification.show("Message sent");
+        }
+    }
+
+    private boolean isValidEmail(String email) {
+        return email.matches("^[A-Za-z0-9+_.-]+@(.+)$");
+    }
+
+    private void enableSendButton() {
+        sendButton.setEnabled(true);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageStore.getMessages());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        String name = nameField.getValue().trim();
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        String message = messageField.getValue().trim();
+
+        boolean hasUnsavedData = !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+
+        if (hasUnsavedData) {
+            event.postpone();
+
+            ConfirmDialog dialog = new ConfirmDialog();
+            dialog.setHeader("Unsaved changes");
+            dialog.setText("You have unsaved changes. Do you want to discard them?");
+            dialog.setCancelable(true);
+            dialog.setConfirmText("Discard");
+            dialog.setCancelText("Keep editing");
+            dialog.addConfirmListener(e -> event.forwardTo(event.getNavigationTarget()));
+            dialog.addCancelListener(e -> {
+            });
+
+            dialog.open();
+        }
+    }
+}
